bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec -i "$cid" node --input-type=module <<'NODE'
import {openCreatorEditor,editCreatorDraft,creatorEditorPanel} from '/opt/videobot/src/telegram/creatorUi.mjs';
let d=openCreatorEditor({sellerId:'55566'});
d=editCreatorDraft(d,{type:'captionTitle',text:'test'});
d=editCreatorDraft(d,{type:'paidVideo',media:{fileId:'video_abc123'}});
d=editCreatorDraft(d,{type:'thumbnail',media:{fileId:'photo_abc123'}});
d=editCreatorDraft(d,{type:'sample',media:{fileId:'sample_abc123',durationSeconds:22.5}});
d=editCreatorDraft(d,{type:'preset',stars:50});
const e=openCreatorEditor({sellerId:'55566',existing:{id:'item_abc',sellerId:'55566',revision:2,title:'test',paidVideo:{fileId:'video_abc123'},thumbnail:{fileId:'photo_abc123'},sample:{fileId:'sample_abc123',durationSeconds:22.5},priceStars:50}});
for(const [tag,draft] of [['CREATE',d],['EDIT',e]]) {
 const p=creatorEditorPanel(draft,3);
 const text=p.text;
 console.log(tag+'_FEE_OR_PAYOUT_IN_PREVIEW='+/販売手数料|運営管理費|管理費\d|取り分|30%|70%|実払出|引き出し可能/.test(text));
 console.log(tag+'_REGISTRATION_GUIDE='+(/登録方法|登録手続き/.test(text)));
 console.log(tag+'_EDIT_GUIDE='+(/編集方法|変更したい項目/.test(text)));
 console.log(tag+'_GUIDE_AFTER_FIELDS='+(text.indexOf('有料本編：')>=0&&(/登録方法|編集方法/.test(text.slice(text.indexOf('有料本編：')+1)))));
 console.log(tag+'_BUTTONS='+p.reply_markup.inline_keyboard[0].map(b=>b.text).join('|'));
 console.log(tag+'_ENTITY_VALID='+p.entities.every(e=>['［編集］','［未登録］'].includes(text.slice(e.offset,e.offset+e.length))));
}
NODE
echo CREATOR_PREVIEW_DIAGNOSTIC_READONLY=PASS
